  const styles = useStyles();
  const [color, setColor] = React.useState(DEFAULT_COLOR_HSV);

  const onSliderChange: ColorSliderProps['onChange'] = (_, data) => {
    setColor({ ...data.color, a: data.color.a ?? 1 });
