    },
    sortDirection: getSortDirection(columnId),
  });

  const keyboardNavAttr = useArrowNavigationGroup({ axis: 'grid' });

  return (
    <Table
      {...keyboardNavAttr}
      role="grid"
      sortable
      aria-label="DataGrid implementation with Table primitives"
      style={{ minWidth: '550px' }}
    >
