export const compatEntryPointLoaded = true;

// scripts/verify-compat.ts
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

interface CompatManifest {
  name: string;
  version: string;
}

export function readCompatManifest(): CompatManifest {
  return require('@fluentui/react-utilities-compat/package.json') as CompatManifest;
}

export function assertCompatMajor(expectedMajor: number): void {
  const { version } = readCompatManifest();
  const installedMajor = Number.parseInt(version.split('.')[0] ?? '', 10);
  if (installedMajor !== expectedMajor) {
    throw new Error(
      `Expected @fluentui/react-utilities-compat v${expectedMajor}.x but found v${version}.`,
    );
  }
}

assertCompatMajor(9);

// scripts/no-deep-imports.ts
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const PACKAGE = '@fluentui/react-utilities-compat';
const DEEP_IMPORT = new RegExp(`(from\\s*|import\\(\\s*)['\"]${PACKAGE}/`);

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((entry) => {
    const full = join(dir, entry);
    return statSync(full).isDirectory() ? walk(full) : [full];
  });
}

export function findDeepCompatImports(root = join(process.cwd(), 'src')): string[] {
  return walk(root)
    .filter((file) => /\.[cm]?[jt]sx?$/.test(file))
    .filter((file) => DEEP_IMPORT.test(readFileSync(file, 'utf8')))
    .map((file) => relative(root, file));
}

const offenders = findDeepCompatImports();
if (offenders.length > 0) {
  throw new Error(
    `Deep imports into ${PACKAGE} are not allowed:\n${offenders.join('\n')}`,
  );
}

