import type * as Compat from '@fluentui/react-utilities-compat';

/**
 * Namespace alias for the compat entry point. It is empty as of the current
 * package surface, which lets consumers keep one import path during migration.
 */
export type CompatNamespace = typeof Compat;

// Non-distributive over a concrete type: evaluates to `true` only while the
// compat namespace exposes no keys.
export type CompatIsEmpty = keyof CompatNamespace extends never ? true : false;

export const compatIsEmpty: CompatIsEmpty = true;

