                if (error) {
                  setError(null);
                }
              }}
            />
          </Field>

          <Field label="Password" required>
            <Input
              type={revealPassword ? 'text' : 'password'}
              name="password"
              autoComplete="current-password"
              value={password}
              onChange={(_, data) => {
                setPassword(data.value);
                if (error) {
                  setError(null);
                }
              }}
              contentAfter={
                <Button
                  type="button"
                  appearance="transparent"
                  size="small"
                  aria-label={revealPassword ? 'Hide password' : 'Show password'}
