  Spinner,
  Text,
} from '@fluentui/react-components';

type ReauthenticateDialogProps = {
  open: boolean;
  onDismiss: () => void;
  onVerified: () => void;
};

// Replace with your real verification call.
async function verifyPassword(password: string): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, 700));
  if (password === 'wrong-password') {
    throw new Error('Invalid password');
  }
}

export const ReauthenticateDialog: React.FC<ReauthenticateDialogProps> = ({
  open,
  onDismiss,
  onVerified,
}) => {
  const [password, setPassword] = React.useState('');
  const [error, setError] = React.useState<string | null>(null);
  const [submitting, setSubmitting] = React.useState(false);

  React.useEffect(() => {
    if (!open) {
      setPassword('');
      setError(null);
      setSubmitting(false);
    }
  }, [open]);

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (!password) {
      setError('Enter your password to continue.');
      return;
    }

    setSubmitting(true);
    setError(null);

    try {
      await verifyPassword(password);
      onVerified();
    } catch {
      setError('That password is not correct.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(_, data) => {
        if (!data.open) {
          onDismiss();
        }
      }}
    >
      <DialogSurface>
        <DialogBody>
          <DialogTitle>Confirm it&#39;s you</DialogTitle>
          <DialogContent>
            <Text block size={300} style={{ marginBottom: '12px' }}>
              For your security we need your password before showing this information.
            </Text>
            <form id="reauthenticate-form" onSubmit={handleSubmit} noValidate>
              <Field
                label="Password"
                required
                validationState={error ? 'error' : 'none'}
                validationMessage={error}
              >
                <Input
                  type="password"
                  name="password"
                  autoComplete="current-password"
                  value={password}
                  onChange={(_, data) => {
                    setPassword(data.value);
                    if (error) {
                      setError(null);
                    }
                  }}
                />
              </Field>
            </form>
          </DialogContent>
          <DialogActions>
            <Button type="button" appearance="secondary" onClick={onDismiss} disabled={submitting}>
              Cancel
            </Button>
            <Button
              type="submit"
              form="reauthenticate-form"
              appearance="primary"
              disabled={submitting}
              icon={submitting ? <Spinner size="tiny" /> : undefined}
            >
              {submitting ? 'Verifying...' : 'Continue'}
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
};

