} from "@fluentui/react-components";

type Plan = "starter" | "standard" | "premium";

interface FormValues {
  fullName: string;
  email: string;
  company: string;
  plan: Plan | "";
  teamSize: string;
  budget: string;
  notes: string;
  acceptedTerms: boolean;
}

type FormErrors = Partial<Record<keyof FormValues, string>>;

const STEPS = ["Account", "Plan", "Review"] as const;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const PLAN_LABELS: Record<Plan, string> = {
  starter: "Starter (5 users, 10 GB)",
  standard: "Standard (25 users, 100 GB)",
  premium: "Premium (unlimited users, 1 TB)",
};

const INITIAL_VALUES: FormValues = {
  fullName: "",
  email: "",
  company: "",
  plan: "",
  teamSize: "",
  budget: "",
  notes: "",
  acceptedTerms: false,
};

function validateStep(step: number, values: FormValues): FormErrors {
  if (step === 0) {
    const errors: FormErrors = {};
    if (!values.fullName.trim()) {
      errors.fullName = "Enter your full name.";
    }
    if (!values.email.trim()) {
      errors.email = "Enter your work email.";
    } else if (!EMAIL_PATTERN.test(values.email.trim())) {
      errors.email = "Enter a valid email address, such as name@company.com.";
    }
    return errors;
  }

  if (step === 1) {
    const errors: FormErrors = {};
    if (!values.plan) {
      errors.plan = "Select the plan you want to start with.";
    }
    if (!values.teamSize) {
      errors.teamSize = "Select how many people will use the workspace.";
    }
    if (values.budget.trim() !== "" && Number.isNaN(Number(values.budget))) {
      errors.budget = "Budget must be a number.";
    }
    return errors;
  }

  return values.acceptedTerms ? {} : { acceptedTerms: "Accept the terms to create your workspace." };
}

export const AccountSetupWizard: React.FC = () => {
  const [step, setStep] = React.useState(0);
  const [values, setValues] = React.useState<FormValues>(INITIAL_VALUES);
  const [errors, setErrors] = React.useState<FormErrors>({});
  const [submitted, setSubmitted] = React.useState(false);

  const update = (patch: Partial<FormValues>) => {
    setValues((previous) => ({ ...previous, ...patch }));
    setErrors((previous) => {
      const patchedKeys = Object.keys(patch) as Array<keyof FormValues>;
      if (!patchedKeys.some((key) => previous[key])) {
        return previous;
      }
      const next = { ...previous };
      patchedKeys.forEach((key) => delete next[key]);
      return next;
    });
  };

  const errorKeys = Object.keys(errors) as Array<keyof FormValues>;
  const isLastStep = step === STEPS.length - 1;

  const goBack = () => {
    setErrors({});
    setStep((current) => Math.max(0, current - 1));
  };

  const goNext = () => {
    const stepErrors = validateStep(step, values);
    setErrors(stepErrors);
    if (Object.keys(stepErrors).length > 0) {
      return;
    }
    if (isLastStep) {
      setSubmitted(true);
    } else {
      setStep((current) => current + 1);
    }
  };

  const startOver = () => {
    setValues(INITIAL_VALUES);
    setErrors({});
    setSubmitted(false);
    setStep(0);
  };

  return (
    <Card appearance="outline" style={{ maxWidth: 620, margin: "0 auto" }}>
      <CardHeader
        header={
          <Text weight="semibold" size={500}>
            Create your workspace
          </Text>
        }
        description={
          <Text size={200}>
            Step {step + 1} of {STEPS.length}: {STEPS[step]}
          </Text>
        }
      />

      <ProgressBar
        value={step + 1}
        max={STEPS.length}
        thickness="large"
        aria-label={`Step ${step + 1} of ${STEPS.length}`}
      />

      <Divider appearance="subtle" />

      {submitted ? (
        <MessageBar intent="success">
          <MessageBarBody>
            <MessageBarTitle>Workspace created</MessageBarTitle>
            <Text>
              {`${values.fullName || "Your account"} is set up on the ${
                values.plan ? PLAN_LABELS[values.plan] : "selected"
              } plan. We sent a confirmation to ${values.email}.`}
            </Text>
          </MessageBarBody>
        </MessageBar>
      ) : (
        <>
          {errorKeys.length > 0 && (
            <MessageBar intent="error" politeness="polite">
              <MessageBarBody>
                <MessageBarTitle>Check the highlighted fields</MessageBarTitle>
                <ul style={{ margin: 0, paddingInlineStart: 20 }}>
                  {errorKeys.map((key) => (
                    <li key={key}>{errors[key]}</li>
                  ))}
                </ul>
              </MessageBarBody>
            </MessageBar>
          )}

          {step === 0 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 16, maxWidth: 420 }}>
              <Field
                label="Full name"
                required
                validationState={errors.fullName ? "error" : "none"}
                validationMessage={errors.fullName}
              >
                {(fieldProps) => (
                  <Input
                    {...fieldProps}
                    value={values.fullName}
                    onChange={(_, data) => update({ fullName: data.value })}
                  />
                )}
              </Field>

              <Field
                label="Work email"
                required
                validationState={errors.email ? "error" : "none"}
                validationMessage={errors.email}
              >
                {(fieldProps) => (
                  <Input
                    {...fieldProps}
                    type="email"
                    value={values.email}
                    onChange={(_, data) => update({ email: data.value })}
                  />
                )}
              </Field>

              <Field label="Company" hint="Optional">
                {(fieldProps) => (
                  <Input
                    {...fieldProps}
                    value={values.company}
                    onChange={(_, data) => update({ company: data.value })}
                  />
                )}
              </Field>
            </div>
          )}

          {step === 1 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 16, maxWidth: 420 }}>
              <Field
                label="Plan"
                required
                hint="You can change your plan at any time."
                validationState={errors.plan ? "error" : "none"}
                validationMessage={errors.plan}
              >
                {(fieldProps) => (
                  <RadioGroup
                    {...fieldProps}
                    value={values.plan}
                    onChange={(_, data) => update({ plan: data.value as Plan })}
                    layout="vertical"
                  >
                    <Radio value="starter" label={PLAN_LABELS.starter} />
                    <Radio value="standard" label={PLAN_LABELS.standard} />
                    <Radio value="premium" label={PLAN_LABELS.premium} />
                  </RadioGroup>
                )}
              </Field>

              <Field
                label="Team size"
                required
                validationState={errors.teamSize ? "error" : "none"}
                validationMessage={errors.teamSize}
              >
                {(fieldProps) => (
                  <Select
                    {...fieldProps}
                    value={values.teamSize}
                    onChange={(_, data) => update({ teamSize: data.value })}
                  >
                    <option value="">Select a range</option>
                    <option value="1-10">1-10 people</option>
                    <option value="11-50">11-50 people</option>
                    <option value="51-200">51-200 people</option>
                    <option value="200+">More than 200 people</option>
                  </Select>
                )}
              </Field>

              <Field
                label="Monthly budget (USD)"
                validationState={errors.budget ? "error" : "none"}
                validationMessage={errors.budget}
              >
                {(fieldProps) => (
                  <Input
                    {...fieldProps}
                    type="number"
                    value={values.budget}
                    onChange={(_, data) => update({ budget: data.value })}
                  />
                )}
              </Field>

              <Field label="Anything we should know?" hint="Optional">
                {(fieldProps) => (
                  <Textarea
                    {...fieldProps}
                    value={values.notes}
                    resize="vertical"
                    onChange={(_, data) => update({ notes: data.value })}
                  />
                )}
              </Field>
            </div>
          )}

          {step === 2 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <Text weight="semibold">Review your details</Text>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "minmax(120px, 160px) 1fr",
                  rowGap: 8,
                  columnGap: 12,
                }}
              >
                <Text size={200} weight="semibold">
                  Name
                </Text>
                <Text>{values.fullName || "-"}</Text>
                <Text size={200} weight="semibold">
                  Email
                </Text>
                <Text>{values.email || "-"}</Text>
                <Text size={200} weight="semibold">
                  Company
                </Text>
                <Text>{values.company || "-"}</Text>
                <Text size={200} weight="semibold">
                  Plan
                </Text>
                <Text>{values.plan ? PLAN_LABELS[values.plan] : "-"}</Text>
                <Text size={200} weight="semibold">
                  Team size
                </Text>
                <Text>{values.teamSize || "-"}</Text>
                <Text size={200} weight="semibold">
                  Budget
                </Text>
                <Text>{values.budget ? `$${values.budget}` : "-"}</Text>
              </div>

              {values.notes && (
                <>
                  <Text size={200} weight="semibold">
                    Notes
                  </Text>
                  <Text>{values.notes}</Text>
                </>
              )}

              <Divider appearance="subtle" />

              <Checkbox
                checked={values.acceptedTerms}
                onChange={(_, data) => update({ acceptedTerms: data.checked === true })}
                label="I accept the terms of service and privacy policy"
              />

              {errors.acceptedTerms && (
                <MessageBar intent="error" politeness="polite">
                  <MessageBarBody>
                    <Text>{errors.acceptedTerms}</Text>
                  </MessageBarBody>
                </MessageBar>
              )}
            </div>
          )}
        </>
      )}

      <CardFooter>
        <div style={{ display: "flex", gap: 8, width: "100%", justifyContent: "flex-end" }}>
          {submitted ? (
            <Button appearance="primary" onClick={startOver}>
              Create another workspace
            </Button>
          ) : (
            <>
              <Button appearance="secondary" disabled={step === 0} onClick={goBack}>
                Back
              </Button>
              <Button appearance="primary" onClick={goNext}>
                {isLastStep ? "Create workspace" : "Next"}
              </Button>
            </>
          )}
        </div>
      </CardFooter>
    </Card>
  );
};

import * as React from "react";
import {
  Button,
  Card,
  CardFooter,
  CardHeader,
  Divider,
  Field,
  Input,
  MessageBar,
  MessageBarBody,
  MessageBarTitle,
  Select,
  Tab,
  TabList,
  Text,
} from "@fluentui/react-components";

type StepKey = "contact" | "delivery" | "payment";

interface CheckoutValues {
  email: string;
  phone: string;
  address: string;
  city: string;
  postcode: string;
  deliverySpeed: string;
  cardName: string;
  cardNumber: string;
}

type CheckoutErrors = Partial<Record<keyof CheckoutValues, string>>;

const STEP_ORDER: StepKey[] = ["contact", "delivery", "payment"];

const STEP_LABELS: Record<StepKey, string> = {
  contact: "Contact",
  delivery: "Delivery",
  payment: "Payment",
};

const INITIAL_VALUES: CheckoutValues = {
  email: "",
  phone: "",
  address: "",
  city: "",
  postcode: "",
  deliverySpeed: "standard",
  cardName: "",
  cardNumber: "",
};

function validateStep(step: StepKey, values: CheckoutValues): CheckoutErrors {
  const errors: CheckoutErrors = {};

  if (step === "contact") {
    if (!values.email.includes("@")) {
      errors.email = "Enter an email address we can send the receipt to.";
    }
    if (values.phone.replace(/\D/g, "").length < 7) {
      errors.phone = "Enter a phone number with at least 7 digits.";
    }
  }

  if (step === "delivery") {
    if (!values.address.trim()) {
      errors.address = "Enter a street address.";
    }
    if (!values.city.trim()) {
      errors.city = "Enter a city.";
    }
    if (!/^[A-Za-z0-9][A-Za-z0-9 -]{2,9}$/.test(values.postcode.trim())) {
      errors.postcode = "Enter a valid postal code (3-10 characters).";
    }
  }

  if (step === "payment") {
    if (!values.cardName.trim()) {
      errors.cardName = "Enter the name printed on the card.";
    }
    if (values.cardNumber.replace(/\s/g, "").length < 12) {
      errors.cardNumber = "Enter a valid card number.";
    }
  }

  return errors;
}

export const CheckoutWizard: React.FC = () => {
  const [currentStep, setCurrentStep] = React.useState<StepKey>("contact");
  const [furthestStep, setFurthestStep] = React.useState(0);
  const [values, setValues] = React.useState<CheckoutValues>(INITIAL_VALUES);
  const [errors, setErrors] = React.useState<CheckoutErrors>({});
  const [confirmation, setConfirmation] = React.useState<string | undefined>();

  const currentIndex = STEP_ORDER.indexOf(currentStep);

  const update = (patch: Partial<CheckoutValues>) => {
    setValues((previous) => ({ ...previous, ...patch }));
    setErrors((previous) => {
      const patchedKeys = Object.keys(patch) as Array<keyof CheckoutValues>;
      if (!patchedKeys.some((key) => previous[key])) {
        return previous;
      }
      const next = { ...previous };
      patchedKeys.forEach((key) => delete next[key]);
      return next;
    });
  };

  const selectStep = (step: StepKey) => {
    if (confirmation) {
      return;
    }
    if (STEP_ORDER.indexOf(step) <= furthestStep) {
      setErrors({});
      setCurrentStep(step);
    }
  };

  const goBack = () => {
    setErrors({});
    setCurrentStep(STEP_ORDER[Math.max(0, currentIndex - 1)]);
  };

  const goNext = () => {
    const stepErrors = validateStep(currentStep, values);
    setErrors(stepErrors);
    if (Object.keys(stepErrors).length > 0) {
      return;
    }
    if (currentIndex === STEP_ORDER.length - 1) {
      setConfirmation(`Order placed. A receipt is on its way to ${values.email}.`);
      return;
    }
    const nextIndex = currentIndex + 1;
    setFurthestStep((previous) => Math.max(previous, nextIndex));
    setCurrentStep(STEP_ORDER[nextIndex]);
  };

  return (
    <Card appearance="outline" style={{ maxWidth: 620, margin: "0 auto" }}>
      <CardHeader
        header={
          <Text weight="semibold" size={500}>
            Checkout
          </Text>
        }
        description={<Text size={200}>Complete each section, then place your order.</Text>}
      />

      <TabList
        selectedValue={currentStep}
        onTabSelect={(_, data) => selectStep(data.value as StepKey)}
        selectTabOnFocus={false}
        aria-label="Checkout steps"
      >
        {STEP_ORDER.map((step, index) => (
          <Tab
            key={step}
            value={step}
            disabled={index > furthestStep || confirmation !== undefined}
          >
            {`${index + 1}. ${STEP_LABELS[step]}`}
          </Tab>
        ))}
      </TabList>

      <Divider appearance="subtle" />

      {confirmation ? (
        <MessageBar intent="success">
          <MessageBarBody>
            <MessageBarTitle>Thank you!</MessageBarTitle>
            <Text>{confirmation}</Text>
          </MessageBarBody>
        </MessageBar>
      ) : (
        <>
          {Object.keys(errors).length > 0 && (
            <MessageBar intent="error" politeness="polite">
              <MessageBarBody>
                <MessageBarTitle>Fix these before continuing</MessageBarTitle>
                <ul style={{ margin: 0, paddingInlineStart: 20 }}>
                  {(Object.keys(errors) as Array<keyof CheckoutValues>).map((key) => (
                    <li key={key}>{errors[key]}</li>
                  ))}
                </ul>
              </MessageBarBody>
            </MessageBar>
          )}

          <div
            role="tabpanel"
            aria-label={STEP_LABELS[currentStep]}
            style={{ display: "flex", flexDirection: "column", gap: 16, maxWidth: 420 }}
          >
            {currentStep === "contact" && (
              <>
                <Field
                  label="Email"
                  required
                  validationState={errors.email ? "error" : "none"}
                  validationMessage={errors.email}
                >
                  {(fieldProps) => (
                    <Input
                      {...fieldProps}
                      type="email"
                      value={values.email}
                      onChange={(_, data) => update({ email: data.value })}
                    />
                  )}
                </Field>

                <Field
                  label="Phone"
                  required
                  validationState={errors.phone ? "error" : "none"}
                  validationMessage={errors.phone}
                >
                  {(fieldProps) => (
                    <Input
                      {...fieldProps}
                      type="tel"
                      value={values.phone}
                      onChange={(_, data) => update({ phone: data.value })}
                    />
                  )}
                </Field>
              </>
            )}

            {currentStep === "delivery" && (
              <>
                <Field
                  label="Street address"
                  required
                  validationState={errors.address ? "error" : "none"}
                  validationMessage={errors.address}
                >
                  {(fieldProps) => (
                    <Input
                      {...fieldProps}
                      value={values.address}
                      onChange={(_, data) => update({ address: data.value })}
                    />
                  )}
                </Field>

                <Field
                  label="City"
                  required
                  validationState={errors.city ? "error" : "none"}
                  validationMessage={errors.city}
                >
                  {(fieldProps) => (
                    <Input
                      {...fieldProps}
                      value={values.city}
                      onChange={(_, data) => update({ city: data.value })}
                    />
                  )}
                </Field>

                <Field
                  label="Postal code"
                  required
                  validationState={errors.postcode ? "error" : "none"}
                  validationMessage={errors.postcode}
                >
                  {(fieldProps) => (
                    <Input
                      {...fieldProps}
                      value={values.postcode}
                      onChange={(_, data) => update({ postcode: data.value })}
                    />
                  )}
                </Field>

                <Field label="Delivery speed">
                  {(fieldProps) => (
                    <Select
                      {...fieldProps}
                      value={values.deliverySpeed}
                      onChange={(_, data) => update({ deliverySpeed: data.value })}
                    >
                      <option value="standard">Standard (3-5 days)</option>
                      <option value="express">Express (next day)</option>
                      <option value="pickup">Pick up in store</option>
                    </Select>
                  )}
                </Field>
              </>
            )}

            {currentStep === "payment" && (
              <>
                <Field
                  label="Name on card"
                  required
                  validationState={errors.cardName ? "error" : "none"}
                  validationMessage={errors.cardName}
                >
                  {(fieldProps) => (
                    <Input
                      {...fieldProps}
                      value={values.cardName}
                      onChange={(_, data) => update({ cardName: data.value })}
                    />
                  )}
                </Field>

                <Field
                  label="Card number"
                  required
                  hint="This demo validates the length only - never store raw card data."
                  validationState={errors.cardNumber ? "error" : "none"}
                  validationMessage={errors.cardNumber}
                >
                  {(fieldProps) => (
                    <Input
                      {...fieldProps}
                      value={values.cardNumber}
                      onChange={(_, data) => update({ cardNumber: data.value })}
                    />
                  )}
                </Field>
              </>
            )}
          </div>
        </>
      )}

      <CardFooter>
        <div style={{ display: "flex", gap: 8, width: "100%", justifyContent: "flex-end" }}>
          <Button
            appearance="secondary"
            onClick={goBack}
            disabled={currentIndex === 0 || confirmation !== undefined}
          >
            Back
          </Button>
          <Button appearance="primary" onClick={goNext} disabled={confirmation !== undefined}>
            {currentIndex === STEP_ORDER.length - 1 ? "Place order" : "Next"}
          </Button>
        </div>
      </CardFooter>
    </Card>
  );
};

import * as React from "react";
import {
  Button,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
  Divider,
  Field,
  Input,
  MessageBar,
  MessageBarBody,
  MessageBarTitle,
  Spinner,
  Text,
} from "@fluentui/react-components";

export interface SubmitConfirmationDialogProps {
  applicantName: string;
  planLabel: string;
  onSubmitted: () => void;
}

const saveApplication = () =>
  new Promise<void>((resolve) => {
    window.setTimeout(resolve, 1200);
  });

export const SubmitConfirmationDialog: React.FC<SubmitConfirmationDialogProps> = ({
  applicantName,
  planLabel,
  onSubmitted,
}) => {
  const [open, setOpen] = React.useState(false);
  const [typedName, setTypedName] = React.useState("");
  const [error, setError] = React.useState<string | undefined>();
  const [saving, setSaving] = React.useState(false);

  const isMatch = typedName.trim().toLowerCase() === applicantName.trim().toLowerCase();

  const handleConfirm = async () => {
    if (!isMatch) {
      setError(`Type "${applicantName}" exactly as written to confirm.`);
      return;
    }
    setError(undefined);
    setSaving(true);
    try {
      await saveApplication();
      setOpen(false);
      setTypedName("");
      onSubmitted();
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <Button appearance="primary" onClick={() => setOpen(true)}>
        Review and submit
      </Button>

      <Dialog open={open} onOpenChange={(_, data) => setOpen(data.open)}>
        <DialogSurface>
          <DialogBody>
            <DialogTitle>Submit your application?</DialogTitle>
            <DialogContent>
              <Text>{`${applicantName} - ${planLabel}`}</Text>
              <Divider appearance="subtle" />
              <Field
                label="Type your full name to confirm"
                required
                validationState={error ? "error" : "none"}
                validationMessage={error}
              >
                {(fieldProps) => (
                  <Input
                    {...fieldProps}
                    value={typedName}
                    onChange={(_, data) => {
                      setTypedName(data.value);
                      setError(undefined);
                    }}
                  />
                )}
              </Field>
            </DialogContent>
            <DialogActions>
              <DialogTrigger action="close" disableButtonEnhancement>
                <Button appearance="secondary" disabled={saving}>
                  Cancel
                </Button>
              </DialogTrigger>
              <Button
                appearance="primary"
                onClick={handleConfirm}
                disabled={saving}
                icon={saving ? <Spinner size="tiny" /> : undefined}
              >
                {saving ? "Submitting..." : "Submit application"}
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>
    </>
  );
};

export const SubmitStepExample: React.FC = () => {
  const [submittedAt, setSubmittedAt] = React.useState<string | undefined>();

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12, maxWidth: 420 }}>
      {submittedAt && (
        <MessageBar intent="success">
          <MessageBarBody>
            <MessageBarTitle>Application submitted</MessageBarTitle>
            <Text>{submittedAt}</Text>
          </MessageBarBody>
        </MessageBar>
      )}

      <SubmitConfirmationDialog
        applicantName="Ada Lovelace"
        planLabel="Standard (25 users, 100 GB)"
        onSubmitted={() => setSubmittedAt(`Submitted at ${new Date().toLocaleTimeString()}.`)}
      />
    </div>
  );
};

recipes.content:
## What this recipe builds

A form whose validity lives in one place, whose messages appear at the right moment, and whose errors are wired to the controls for assistive technology. It uses `Field` as the validation shell, `Input` / `Textarea` / `Select` / `Checkbox` as controls, `MessageBar` for form-level feedback and `Button` to submit.

## Step 1 - Wrap every validated control in `Field`

`Field` is the only Fluent UI React v9 component that models validation. It renders the label, the hint, the validation message and the message icon, and injects the ARIA wiring into the control through context:

- `label` - renders the `<label>` element and gives the control its accessible name.
- `required` - renders the required indicator and marks the control as required. Native enforcement stays off because the `<form>` is `noValidate`.
- `hint` - always-visible help text (format rules, ranges, character counts). It becomes part of the control's `aria-describedby`.
- `validationState` - `'none' | 'error' | 'warning' | 'success'`. `'error'` sets `aria-invalid="true"` on the control and switches the message to the error style with an icon.
- `validationMessage` - the dynamic message. It renders nothing when `undefined` and is added to `aria-describedby`.
- `orientation` - `'vertical'` (default) or `'horizontal'` when the label should sit beside the control in dense layouts.
- `size` - `'small' | 'medium' | 'large'` for compact layouts.

The controls `Input`, `Textarea`, `Select`, `Checkbox`, `RadioGroup`, `Dropdown`, `Combobox`, `Switch`, `Slider` and `SpinButton` read that context, so you never hand-write `htmlFor`, `id`, `aria-describedby` or `aria-invalid`.

## Step 2 - Model values, derive errors

Keep exactly one copy of the data. Errors are computed, never stored:

```tsx
type FormValues = { email: string; acceptTerms: boolean };
type FormErrors = Partial<Record<keyof FormValues, string>>;

const errors = React.useMemo(() => validate(values), [values]);
const isInvalid = Object.keys(errors).length > 0;
```

Because `errors` is derived, a field stops being invalid the moment its value becomes valid - there is no stale message to clear by hand.

## Step 3 - Decide when a message becomes visible

Store only two extra pieces of UI state: which fields the user has visited, and whether the form has been submitted.

```tsx
const [touched, setTouched] = React.useState<Partial<Record<keyof FormValues, boolean>>>({});
const [submitCount, setSubmitCount] = React.useState(0);
const submitAttempted = submitCount > 0;

const visibleError = (field: keyof FormValues) =>
  touched[field] || submitAttempted ? errors[field] : undefined;

const validationStateFor = (field: keyof FormValues) =>
  visibleError(field) ? 'error' : 'none';
```

Recommended timing:

- First render: no messages, `validationState="none"`.
- `onBlur` of a field: mark it touched so its rule is evaluated and shown.
- `onChange` after a failed submit: `submitAttempted` stays `true`, so errors clear live while the user fixes them.
- `Select`, `RadioGroup`, `Checkbox`: mark touched inside the change handler - a picked value is a committed answer.

## Step 4 - Render hint and message on the field

```tsx
<Field
  label="Work email"
  required
  hint="We only use this address for account notifications."
  validationState={validationStateFor('email')}
  validationMessage={visibleError('email')}
>
  <Input
    value={values.email}
    onChange={(_, data) => updateValue('email', data.value)}
    onBlur={markTouched('email')}
  />
</Field>
```

Change-event data shapes: `InputOnChangeData.value`, `TextareaOnChangeData.value` and `SelectOnChangeData.value` are strings, while `CheckboxOnChangeData.checked` is `boolean | 'mixed'`, so compare with `data.checked === true`.

Use `validationState="warning"` for soft advice (a background check that could not run, a recommended-but-optional rule) and `"success"` to confirm a rule that only passes after work (a strong password, an available username). Keep one message per field: put the single next action in `validationMessage` and persistent rules in `hint`.

## Step 5 - Summarize at the form level and move focus

Field-level messages only help if the user can reach them. After a failed submit, render a `MessageBar` summary and focus the first invalid control:

```tsx
const formRef = React.useRef<HTMLFormElement>(null);

React.useEffect(() => {
  if (submitCount === 0) return;
  formRef.current?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus();
}, [submitCount]);
```

The lookup leans on the `aria-invalid` that `Field` puts on the control when `validationState` is `'error'`, so it always lands on the focusable element itself (the `<input>`, `<select>` or `<textarea>`). Custom focus logic per field is then unnecessary.

The submit handler stays tiny:

```tsx
const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
  event.preventDefault();
  setSubmitCount(count => count + 1);
  if (!isInvalid) setSaved(true);
};
```

Keep the submit `Button` enabled. A disabled button cannot explain what is wrong, and a user who cannot see the screen never learns why it does nothing. Only disable it for transient reasons such as an in-flight async check, and say so with a `Spinner`.

## Step 6 - Cross-field and asynchronous rules

- Cross-field: compute both sides from the same `values` object (password vs. confirmation, start vs. end date) and give each control its own `validationState` and `validationMessage`, so a mismatch can mark the second field while the first stays `success`.
- Async (username availability, coupon codes): keep a status string such as `'idle' | 'checking' | 'available' | 'taken' | 'unknown'`, debounce with `setTimeout` inside `useEffect`, and clean up with a `cancelled` flag so an out-of-order response cannot overwrite a newer one. Show progress in the `Input`'s `contentAfter` slot with `Spinner size="extra-tiny"`, then map the outcome onto `validationState`: `'taken'` becomes `error`, `'unknown'` becomes `warning` (submitting is still allowed and the server re-checks), `'available'` becomes `success`.
- Server-side errors: reuse the same `FormErrors` shape. Set the returned per-field errors into state and render them through the identical `validationMessage` props; put whole-form errors in the `MessageBar`.

## Step 7 - Pre-ship check list

- The `<form>` has `noValidate`, so browser bubbles never pre-empt your messages.
- Every control sits inside a `Field` with a real `label` (never a placeholder used as a label).
- Errors are derived from values with `useMemo`; the only extra state is `touched`, `submitAttempted` and async status.
- `validationState` and `validationMessage` are always set together.
- Focus moves to the first invalid control after a failed submit.
- Async validation cancels stale responses and never blocks submit on an unknown result.
- The submit button is enabled and the form explains itself through messages.

