  /** Route the crumb points at. */
  href: string;
}

export const workspaceCrumbs: Crumb[] = [
  { id: 'home', label: 'Home', href: '/' },
  { id: 'projects', label: 'Projects', href: '/projects' },
  { id: 'contoso', label: 'Contoso', href: '/projects/contoso' },
