        const isCurrent = index === crumbs.length - 1;

        return (
          <React.Fragment key={crumb.id}>
            <BreadcrumbItem>
              <BreadcrumbButton
                current={isCurrent}
                onClick={isCurrent ? undefined : () => navigate(crumb)}
              >
                {crumb.label}
              </BreadcrumbButton>
            </BreadcrumbItem>
            {!isCurrent ? <BreadcrumbDivider /> : null}
          </React.Fragment>
        );
      })}
    </Breadcrumb>
  );
};

