const createIcon = (path: string): React.FC => {
  const Icon: React.FC = () => (
    <svg viewBox='0 0 20 20' width='20' height='20' aria-hidden='true' focusable='false'>
      <path d={path} fill='currentColor' />
    </svg>
  );
  return Icon;
};

