} from '@fluentui/react-components';

type FormState = {
  email: string;
  notes: string;
  plan: string;
  newsletter: boolean;
  alerts: boolean;
  seats: number;
};

const INITIAL_FORM: FormState = {
  email: '',
  notes: '',
  plan: 'team',
  newsletter: false,
  alerts: true,
  seats: 3,
};

export const ControlledForm = () => {
  // Single source of truth for the whole form.
  const [form, setForm] = React.useState<FormState>(INITIAL_FORM);
  // Controlled Dialog: the parent owns 'open', so the Confirm button can close it.
  const [reviewOpen, setReviewOpen] = React.useState(false);

  // Functional update keeps the handler free of stale closures.
  const update = (patch: Partial<FormState>) => {
    setForm((prev) => ({ ...prev, ...patch }));
  };

  const emailValid = /^[^@\s]+@[^@\s]+$/.test(form.email);
  const showEmailError = form.email.length > 0 && !emailValid;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16, maxWidth: 420 }}>
      <Text size={400} weight='semibold' block>
        Controlled form
      </Text>

      <Field
        label='Work email'
        required
        validationState={showEmailError ? 'error' : 'none'}
        validationMessage={showEmailError ? 'Enter a valid email address' : undefined}
      >
        <Input
          type='email'
          value={form.email}
          onChange={(_, data) => update({ email: data.value })}
        />
      </Field>

      <Field label='Notes'>
        <Textarea
          resize='vertical'
          value={form.notes}
          onChange={(_, data) => update({ notes: data.value })}
        />
      </Field>

      <Field label='Plan'>
        <RadioGroup
          value={form.plan}
          onChange={(_, data) => update({ plan: data.value })}
        >
          <Radio value='personal' label='Personal' />
          <Radio value='team' label='Team' />
          <Radio value='enterprise' label='Enterprise' />
        </RadioGroup>
      </Field>

      {/* Checkbox is tri-state capable, so coerce 'mixed' to a boolean for this form. */}
      <Checkbox
        label='Email me product news'
        checked={form.newsletter}
        onChange={(_, data) => update({ newsletter: data.checked === true })}
      />

      <Switch
        label='Desktop notifications'
        checked={form.alerts}
        onChange={(_, data) => update({ alerts: data.checked })}
      />

      <Field label={`Seats: ${form.seats}`}>
        <Slider
          min={1}
          max={25}
          value={form.seats}
          onChange={(_, data) => update({ seats: data.value })}
        />
      </Field>

      <div style={{ display: 'flex', gap: 8 }}>
        <Button appearance='secondary' onClick={() => setForm(INITIAL_FORM)}>
          Reset
        </Button>

        <Dialog open={reviewOpen} onOpenChange={(_, data) => setReviewOpen(data.open)}>
          <DialogTrigger disableButtonEnhancement>
            <Button appearance='primary' disabled={!emailValid}>
              Review and submit
            </Button>
          </DialogTrigger>
          <DialogSurface>
            <DialogBody>
              <DialogTitle>Review your request</DialogTitle>
              <DialogContent>
                <Text block>Email: {form.email}</Text>
                <Text block>Plan: {form.plan}</Text>
                <Text block>Seats: {form.seats}</Text>
              </DialogContent>
              <DialogActions>
                <DialogTrigger disableButtonEnhancement action='close'>
                  <Button appearance='secondary'>Cancel</Button>
                </DialogTrigger>
                <Button appearance='primary' onClick={() => setReviewOpen(false)}>
                  Confirm
                </Button>
              </DialogActions>
            </DialogBody>
          </DialogSurface>
        </Dialog>
      </div>
    </div>
  );
};

import * as React from 'react';
import { Button, Checkbox, Switch, Text } from '@fluentui/react-components';

/** Mirrors the Fluent convention: `value` controls, `defaultValue` seeds, `onChange` always fires. */
function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void,
) {
  const isControlled = value !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState<T>(defaultValue);
  const current = isControlled ? (value as T) : uncontrolled;

  const setValue = React.useCallback(
    (next: T) => {
      if (!isControlled) {
        setUncontrolled(next);
      }
      onChange?.(next);
    },
    [isControlled, onChange],
  );

  return [current, setValue] as const;
}

type DisclosureProps = {
  title: string;
  children: React.ReactNode;
  /** Controlled: pass this together with onOpenChange. */
  open?: boolean;
  /** Uncontrolled: the initial value, ignored after mount. */
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
};

export const Disclosure: React.FC<DisclosureProps> = ({
  title,
  children,
  open,
  defaultOpen = false,
  onOpenChange,
}) => {
  const [isOpen, setIsOpen] = useControllableState(open, defaultOpen, onOpenChange);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      <Switch checked={isOpen} onChange={(_, data) => setIsOpen(data.checked)} label={title} />
      {isOpen && <Text block>{children}</Text>}
    </div>
  );
};

export const OptionalControlledExample = () => {
  const [parentControlled, setParentControlled] = React.useState(false);
  const [parentOpen, setParentOpen] = React.useState(false);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12, maxWidth: 420 }}>
      <Checkbox
        checked={parentControlled}
        onChange={(_, data) => setParentControlled(data.checked === true)}
        label='Let the parent own the state'
      />

      <Button disabled={!parentControlled} onClick={() => setParentOpen((o) => !o)}>
        Toggle from the parent (only works when controlled)
      </Button>

      {parentControlled ? (
        <Disclosure title='Details' open={parentOpen} onOpenChange={setParentOpen}>
          The parent owns this state, so the external button works.
        </Disclosure>
      ) : (
        <Disclosure title='Details' defaultOpen>
          This instance owns its own state; the external button is ignored.
        </Disclosure>
      )}
    </div>
  );
};

// ----------------------------------------------------------------
// useServerResource.ts
// ----------------------------------------------------------------
import * as React from 'react';

export interface ServerResource<T> {
  data: T | undefined;
  error: Error | undefined;
  /** True only while the first payload is in flight and nothing is cached yet. */
  isInitialLoading: boolean;
  /** True while re-fetching with data already on screen (stale-while-revalidate). */
  isRefreshing: boolean;
  /** Epoch milliseconds of the last successful payload. */
  updatedAt: number | undefined;
  /** Re-run the fetcher; existing data stays visible. Identity is stable. */
  refresh: () => void;
}

type InternalState<T> = Omit<ServerResource<T>, 'refresh'>;

export function useServerResource<T>(
  key: string,
  fetcher: (signal: AbortSignal) => Promise<T>,
): ServerResource<T> {
  const [state, setState] = React.useState<InternalState<T>>({
    data: undefined,
    error: undefined,
    isInitialLoading: true,
    isRefreshing: false,
    updatedAt: undefined,
  });

  // Keep the newest fetcher in a ref so an inline arrow does not re-trigger requests.
  const fetcherRef = React.useRef(fetcher);
  fetcherRef.current = fetcher;

  // Monotonic request id: only the newest response may write to state.
  const requestIdRef = React.useRef(0);
  const controllerRef = React.useRef<AbortController | null>(null);

  const run = React.useCallback(() => {
    const requestId = ++requestIdRef.current;
    controllerRef.current?.abort();

    const controller = new AbortController();
    controllerRef.current = controller;

    setState(previous => ({
      ...previous,
      error: undefined,
      isInitialLoading: previous.data === undefined,
      isRefreshing: previous.data !== undefined,
    }));

    fetcherRef.current(controller.signal).then(
      data => {
        if (requestId !== requestIdRef.current || controller.signal.aborted) {
          return; // superseded by a newer request, or cancelled
        }
        setState({
          data,
          error: undefined,
          isInitialLoading: false,
          isRefreshing: false,
          updatedAt: Date.now(),
        });
      },
      (cause: unknown) => {
        if (requestId !== requestIdRef.current || controller.signal.aborted) {
          return;
        }
        setState(previous => ({
          ...previous,
          error: cause instanceof Error ? cause : new Error(String(cause)),
          isInitialLoading: false,
          isRefreshing: false,
        }));
      },
    );
  }, []);

  React.useEffect(() => {
    run();
    // Abort on unmount and whenever the request identity changes.
    return () => controllerRef.current?.abort();
  }, [key, run]);

  return React.useMemo(() => ({ ...state, refresh: run }), [state, run]);
}

// ----------------------------------------------------------------
// AsyncBoundary.tsx
// ----------------------------------------------------------------
import {
  Button,
  MessageBar,
  MessageBarActions,
  MessageBarBody,
  MessageBarTitle,
  Skeleton,
  SkeletonItem,
  Spinner,
  Text,
} from '@fluentui/react-components';
import type { ServerResource } from './useServerResource';

export interface AsyncBoundaryProps<T> {
  resource: ServerResource<T>;
  /** First-load placeholder. Match the final layout so nothing shifts. */
  skeleton?: React.ReactNode;
  loadingLabel?: string;
  /** Return true when the payload loaded successfully but has nothing to show. */
  isEmpty?: (data: T) => boolean;
  emptyTitle?: string;
  emptyMessage?: string;
  children: (data: T) => React.ReactNode;
}

export function AsyncBoundary<T>({
  resource,
  skeleton,
  loadingLabel = 'Loading…',
  isEmpty,
  emptyTitle = 'Nothing here yet',
  emptyMessage = 'Content will appear as soon as it is available.',
  children,
}: AsyncBoundaryProps<T>) {
  const { data, error, isInitialLoading, isRefreshing, refresh } = resource;

  // 1. First load: nothing cached yet.
  if (isInitialLoading && data === undefined) {
    return skeleton ? (
      <>{skeleton}</>
    ) : (
      <Spinner labelPosition='below' size='medium' delay={300}>
        {loadingLabel}
      </Spinner>
    );
  }

  // 2. Failure with nothing to fall back to.
  if (error && data === undefined) {
    return (
      <MessageBar intent='error' politeness='assertive'>
        <MessageBarBody>
          <MessageBarTitle>We could not load this content</MessageBarTitle>
          {error.message}
        </MessageBarBody>
        <MessageBarActions>
          <Button appearance='secondary' onClick={refresh}>
            Try again
          </Button>
        </MessageBarActions>
      </MessageBar>
    );
  }

  if (data === undefined) {
    return null;
  }

  // 3. Success, but empty.
  if (isEmpty?.(data)) {
    return (
      <div style={{ display: 'grid', gap: 4, justifyItems: 'center', padding: 32 }}>
        <Text size={400} weight='semibold' block>
          {emptyTitle}
        </Text>
        <Text size={200} block>
          {emptyMessage}
        </Text>
      </div>
    );
  }

  // 4. Success, optionally with a non-blocking warning over stale data.
  return (
    <>
      {error ? (
        <MessageBar intent='warning'>
          <MessageBarBody>
            <MessageBarTitle>Showing previously loaded data</MessageBarTitle>
            {`The latest refresh failed: ${error.message}`}
          </MessageBarBody>
          <MessageBarActions>
            <Button appearance='secondary' onClick={refresh} disabled={isRefreshing}>
              Retry
            </Button>
          </MessageBarActions>
        </MessageBar>
      ) : null}
      <div aria-busy={isRefreshing}>{children(data)}</div>
    </>
  );
}

