// CreateUserForm.tsx
import * as React from 'react';
import {
  Button,
  Field,
  Input,
  MessageBar,
  MessageBarActions,
  MessageBarBody,
  MessageBarTitle,
  Spinner,
} from '@fluentui/react-components';

interface CreateUserInput {
  name: string;
  email: string;
}

type FieldErrors = Partial<Record<keyof CreateUserInput, string>>;

class ValidationError extends Error {
  readonly fieldErrors: FieldErrors;

  constructor(fieldErrors: FieldErrors) {
    super('The server rejected the submitted values.');
    this.name = 'ValidationError';
    this.fieldErrors = fieldErrors;
  }
}

async function createUser(input: CreateUserInput): Promise<{ id: string }> {
  const response = await fetch('/api/users', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });

  if (response.status === 422) {
    const payload = (await response.json()) as { errors: FieldErrors };
    throw new ValidationError(payload.errors);
  }
  if (!response.ok) {
    throw new Error(`POST /api/users failed with ${response.status}`);
  }
  return (await response.json()) as { id: string };
}

export interface CreateUserFormProps {
  onCreated?: (id: string) => void;
}

export function CreateUserForm({ onCreated }: CreateUserFormProps) {
  const [values, setValues] = React.useState<CreateUserInput>({ name: '', email: '' });
  const [fieldErrors, setFieldErrors] = React.useState<FieldErrors>({});
  const [formError, setFormError] = React.useState<Error | undefined>(undefined);
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [createdId, setCreatedId] = React.useState<string | undefined>(undefined);
  const isMountedRef = React.useRef(true);

  React.useEffect(
    () => () => {
      isMountedRef.current = false;
    },
    [],
  );

  const handleChange =
    (field: keyof CreateUserInput) =>
    (_event: React.ChangeEvent<HTMLInputElement>, data: { value: string }) => {
      setValues(current => ({ ...current, [field]: data.value }));
      // Clear the server error as soon as the user edits the field.
      setFieldErrors(current => ({ ...current, [field]: undefined }));
    };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isSubmitting) {
      return;
    }

    setIsSubmitting(true);
    setFormError(undefined);
    setCreatedId(undefined);

    try {
      const created = await createUser(values);
      if (!isMountedRef.current) return;
      setValues({ name: '', email: '' });
      setFieldErrors({});
      setCreatedId(created.id);
      onCreated?.(created.id);
    } catch (cause) {
      if (!isMountedRef.current) return;
      if (cause instanceof ValidationError) {
        setFieldErrors(cause.fieldErrors);
      } else {
        setFormError(cause instanceof Error ? cause : new Error(String(cause)));
      }
    } finally {
      if (isMountedRef.current) {
        setIsSubmitting(false);
      }
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ display: 'grid', gap: 16, maxWidth: 480 }}>
      {formError ? (
        <MessageBar intent='error' politeness='assertive'>
          <MessageBarBody>
            <MessageBarTitle>Could not create the user</MessageBarTitle>
            {formError.message}
          </MessageBarBody>
          <MessageBarActions>
            <Button appearance='transparent' onClick={() => setFormError(undefined)}>
              Dismiss
            </Button>
          </MessageBarActions>
        </MessageBar>
      ) : null}

      {createdId ? (
        <MessageBar intent='success' politeness='polite'>
          <MessageBarBody>
            <MessageBarTitle>User created</MessageBarTitle>
            {`Server id: ${createdId}`}
          </MessageBarBody>
        </MessageBar>
      ) : null}

      <Field
        label='Name'
        required
        validationState={fieldErrors.name ? 'error' : 'none'}
        validationMessage={fieldErrors.name}
      >
        <Input
          value={values.name}
          onChange={handleChange('name')}
          disabled={isSubmitting}
        />
      </Field>

      <Field
        label='Email'
        required
        validationState={fieldErrors.email ? 'error' : 'none'}
        validationMessage={fieldErrors.email}
      >
        <Input
          type='email'
          value={values.email}
          onChange={handleChange('email')}
          disabled={isSubmitting}
        />
      </Field>

      <Button
        type='submit'
        appearance='primary'
        disabled={isSubmitting}
        icon={isSubmitting ? <Spinner size='extra-tiny' /> : undefined}
      >
        {isSubmitting ? 'Creating…' : 'Create user'}
      </Button>
    </form>
  );
}

// LiveOrders.tsx — depends on AsyncBoundary and useServerResource from Example 1.
import * as React from 'react';
import { Badge, Button, Skeleton, SkeletonItem, Spinner, Text } from '@fluentui/react-components';
import { AsyncBoundary } from './AsyncBoundary';
import { useServerResource } from './useServerResource';

interface Order {
  id: string;
  status: 'open' | 'shipped';
  total: number;
}

async function fetchOrders(signal: AbortSignal): Promise<Order[]> {
  const response = await fetch('/api/orders', { signal });
  if (!response.ok) {
    throw new Error(`GET /api/orders failed with ${response.status}`);
  }
  return (await response.json()) as Order[];
}

function OrderSkeleton() {
  return (
    <Skeleton animation='wave'>
      <div style={{ display: 'grid', gap: 8 }}>
        {Array.from({ length: 4 }, (_, index) => (
          <SkeletonItem key={index} shape='rectangle' />
        ))}
      </div>
    </Skeleton>
  );
}

export function LiveOrders() {
  const orders = useServerResource<Order[]>('orders:live', fetchOrders);
  const [isPaused, setIsPaused] = React.useState(false);
  const { refresh } = orders;

  React.useEffect(() => {
    if (isPaused) {
      return;
    }

    const intervalId = window.setInterval(() => {
      // Never poll a hidden tab: it wastes the user's battery and data plan.
      if (document.visibilityState === 'visible') {
        refresh();
      }
    }, 15000);

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        refresh();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      window.clearInterval(intervalId);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [isPaused, refresh]);

  return (
    <div style={{ display: 'grid', gap: 12 }}>
      <header style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <h2 style={{ margin: 0 }}>
          <Text size={500} weight='semibold'>
            Live orders
          </Text>
        </h2>
        <Badge appearance='tint' color={isPaused ? 'informative' : 'success'}>
          {isPaused ? 'Paused' : 'Live · 15s'}
        </Badge>

        <span style={{ flex: 1 }} />

        <Button
          appearance='secondary'
          onClick={refresh}
          disabled={orders.isRefreshing}
          icon={orders.isRefreshing ? <Spinner size='extra-tiny' /> : undefined}
        >
          Refresh now
        </Button>
        <Button appearance='subtle' onClick={() => setIsPaused(previous => !previous)}>
          {isPaused ? 'Resume polling' : 'Pause polling'}
        </Button>
      </header>

      <AsyncBoundary
        resource={orders}
        skeleton={<OrderSkeleton />}
        loadingLabel='Loading orders'
        isEmpty={list => list.length === 0}
        emptyTitle='No open orders'
        emptyMessage='New orders appear here automatically.'
      >
        {list => (
          <ul style={{ margin: 0, paddingLeft: 20 }}>
            {list.map(order => (
              <li key={order.id}>
                {order.id} — {order.status} — ${order.total.toFixed(2)}
              </li>
            ))}
          </ul>
        )}
      </AsyncBoundary>
    </div>
  );
}

import * as React from 'react';
import {
  Button,
  Checkbox,
  Field,
  Input,
  MessageBar,
  MessageBarBody,
  MessageBarTitle,
  Radio,
  RadioGroup,
  Select,
  Switch,
  Text,
  Textarea,
} from '@fluentui/react-components';

type AccountSettings = {
  displayName: string;
  email: string;
  role: string;
  bio: string;
  theme: string;
  digest: boolean;
  twoFactor: boolean;
};

type FieldErrors = Partial<Record<'displayName' | 'email', string>>;

const initialSettings: AccountSettings = {
  displayName: '',
  email: '',
  role: 'engineer',
  bio: '',
  theme: 'system',
  digest: true,
  twoFactor: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export const AccessibleSettingsForm: React.FC = () => {
  const [settings, setSettings] = React.useState<AccountSettings>(initialSettings);
  const [errors, setErrors] = React.useState<FieldErrors>({});
  const [status, setStatus] = React.useState<string | undefined>(undefined);

  const update = <K extends keyof AccountSettings>(key: K, value: AccountSettings[K]) => {
    setSettings(previous => ({ ...previous, [key]: value }));
  };

  const validate = (candidate: AccountSettings): FieldErrors => {
    const nextErrors: FieldErrors = {};
    if (candidate.displayName.trim().length === 0) {
      nextErrors.displayName = 'Enter a display name so teammates can recognize you.';
    }
    if (!EMAIL_PATTERN.test(candidate.email)) {
      nextErrors.email = 'Enter an email address in the format name@example.com.';
    }
    return nextErrors;
  };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const nextErrors = validate(settings);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) {
      setStatus(undefined);
      return;
    }
    setStatus(`Settings saved for ${settings.displayName}.`);
  };

  const errorCount = Object.keys(errors).length;

  return (
    <form onSubmit={handleSubmit} noValidate style={{ display: 'grid', gap: 16, maxWidth: 480 }}>
      <h2>
        <Text size={600} weight="semibold">
          Account settings
        </Text>
      </h2>

      {/* Summary of errors is announced immediately, assertively. */}
      {errorCount > 0 && (
        <MessageBar intent="error" politeness="assertive">
          <MessageBarBody>
            <MessageBarTitle>
              {errorCount === 1 ? 'One field needs attention' : `${errorCount} fields need attention`}
            </MessageBarTitle>
            Fix the highlighted fields, then save again.
          </MessageBarBody>
        </MessageBar>
      )}

      {/* Success is polite: it never interrupts the user mid-sentence. */}
      {status && (
        <MessageBar intent="success" politeness="polite">
          <MessageBarBody>
            <MessageBarTitle>Saved</MessageBarTitle>
            {status}
          </MessageBarBody>
        </MessageBar>
      )}

      {/* Field links label, hint and validation message to the Input. */}
      <Field
        label="Display name"
        required
        hint="Shown next to your comments and mentions."
        validationState={errors.displayName ? 'error' : 'none'}
        validationMessage={errors.displayName}
      >
        <Input
          value={settings.displayName}
          onChange={(_, data) => update('displayName', data.value)}
        />
      </Field>

      <Field
        label="Email address"
        required
        hint="Used only for account recovery."
        validationState={errors.email ? 'error' : 'none'}
        validationMessage={errors.email}
      >
        <Input
          type="email"
          value={settings.email}
          onChange={(_, data) => update('email', data.value)}
        />
      </Field>

      <Field label="Role" hint="Controls which dashboards you can open.">
        <Select value={settings.role} onChange={(_, data) => update('role', data.value)}>
          <option value="engineer">Engineer</option>
          <option value="designer">Designer</option>
          <option value="manager">Manager</option>
        </Select>
      </Field>

      <Field label="Bio" hint="Plain text only, 280 characters maximum.">
        <Textarea
          value={settings.bio}
          resize="vertical"
          onChange={(_, data) => update('bio', data.value)}
        />
      </Field>

      {/* A Field around RadioGroup names the whole group, not one radio. */}
      <Field label="Appearance">
        <RadioGroup
          layout="horizontal"
          value={settings.theme}
          onChange={(_, data) => update('theme', data.value)}
        >
          <Radio value="system" label="Match system" />
          <Radio value="light" label="Light" />
          <Radio value="dark" label="Dark" />
        </RadioGroup>
      </Field>

      {/* Checkbox and Switch carry their own label slot - no Field wrapper. */}
      <Checkbox
        label="Email me a weekly digest"
        checked={settings.digest}
        onChange={(_, data) => update('digest', data.checked === true)}
      />

      <Switch
        label="Require two-factor authentication"
        checked={settings.twoFactor}
        onChange={(_, data) => update('twoFactor', data.checked)}
      />

      <div style={{ display: 'flex', gap: 8 }}>
        <Button type="submit" appearance="primary">
          Save settings
        </Button>
        <Button
          type="button"
          appearance="secondary"
          onClick={() => {
            setSettings(initialSettings);
            setErrors({});
            setStatus(undefined);
          }}
        >
          Reset
        </Button>
      </div>
    </form>
  );
};

