export const Tags = ({ tags, remove }: { tags: string[]; remove: (v: string) => void }) => (
  <TagGroup dismissible onDismiss={(_, data) => remove(data.value as string)}>
    {tags.map(tag => (
      <Tag key={tag} value={tag} dismissible>{tag}</Tag>
